package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="app_users") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) @Column(nullable=false) private Statuses.UserRole role; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="driver_id") private Driver driver; private boolean enabled=true; @Column(name="created_at") private Instant createdAt; @PrePersist void created(){createdAt=Instant.now();} public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v.toLowerCase();} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Statuses.UserRole getRole(){return role;} public void setRole(Statuses.UserRole v){role=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} }
